const r="// 原生 Vue 3 Toolbar 注入演示脚本 - 使用 registerFunction 注册函数\r\n// 上下文变量：$api, $route, $data, $el, $query, $queryAll, $rebindRules, $refreshData, $dataSet, $call 都已注入\r\n\r\n// 页面初始化\r\nregisterFunction('__init__', () => {\r\n  console.log('Toolbar Inject Native Demo initialized')\r\n})\r\n\r\n// 可以在这里添加更多逻辑，比如处理按钮点击事件\r\nregisterFunction('handleAddUser', () => {\r\n  console.log('添加用户按钮被点击')\r\n})\r\n\r\nregisterFunction('handleExportData', () => {\r\n  console.log('导出数据按钮被点击')\r\n})";export{r as default};
